406	<script>
407	import router from '@system.router'
408	import vibrator from '@system.vibrator'
409	import imuManager from '../../common/imu-manager'
410	import healthMonitor from '../../common/health-monitor'
411	import sensorFusion from '../../common/sensor-fusion'
412	import swingDetector from '../../common/swing-detector'
413	import shotClassifier from '../../common/shot-classifier'
414	import dataStore from '../../common/data-store'
415	
416	export default {
417	  data: {
418	    currentTab: 0,
419	    modeLabel: '自由训练',
420	    duration: '00:00',
421	    heartRate: null,
422	    calories: 0,
423	    totalStrokes: 0,
424	    lastShotType: '',
425	    shotDistribution: [
426	      { name: '高远球', count: 0, percentage: 10 },
427	      { name: '杀球', count: 0, percentage: 10 },
428	      { name: '平抽', count: 0, percentage: 10 },
429	      { name: '挑球', count: 0, percentage: 10 },
430	      { name: '吊球', count: 0, percentage: 10 }
431	    ],
432	    steps: 0,
433	    distance: 0,
434	    jumps: 0,
435	    highIntensityPercent: 0,
436	    isRunning: false,
437	    startTime: null,
438	    timer: null,
439	    config: null,
440	    healthListener: null,
441	    imuListener: null
442	  },
443	
444	  onInit() {
445	    // 解析训练配置
446	    if (this.config) {
447	      try {
448	        this.config = JSON.parse(this.config)
449	        this.modeLabel = this.getModeLabel(this.config.mode)
450	      } catch (e) {
451	        this.config = {}
452	      }
453	    }
454	
455	    // 初始化模块
456	    this.initModules()
457	  },
458	
459	  onReady() {
460	    // 页面渲染完成后启动训练
461	    this.startTraining()
462	  },
463	
464	  onDestroy() {
465	    this.stopTraining()
466	    this.removeListeners()
467	  },
468	
469	  initModules() {
470	    // 初始化数据存储
471	    dataStore.init()
472	
473	    // 设置挥拍检测回调
474	    swingDetector.onSwingDetected = (swingData) => {
475	      this.handleSwingDetected(swingData)
476	    }
477	
478	    // 保存健康监测监听器引用
479	    this.healthListener = (data) => {
480	      this.handleHealthData(data)
481	    }
482	    healthMonitor.addListener(this.healthListener)
483	
484	    // 设置分类器回调
485	    shotClassifier.onClassification = () => {}
486	  },
487	
488	  removeListeners() {
489	    if (this.healthListener) {
490	      healthMonitor.removeListener(this.healthListener)
491	      this.healthListener = null
492	    }
493	  },
494	
495	  getModeLabel(mode) {
496	    const labels = {
497	      'free': '自由训练',
498	      'singles': '单打比赛',
499	      'doubles': '双打比赛',
500	      'multiball': '多拍训练'
501	    }
502	    return labels[mode] || '自由训练'
503	  },
504	
505	  onTabChange(e) {
506	    this.currentTab = e.index
507	  },
508	
509	  startTraining() {
510	    this.isRunning = true
511	    this.startTime = Date.now()
512	
513	    // 开始新会话
514	    dataStore.startSession()
515	
516	    // 保存 IMU 监听器引用并启动
517	    this.imuListener = (data) => {
518	      this.handleIMUData(data)
519	    }
520	    imuManager.addListener(this.imuListener)
521	    imuManager.start()
522	
523	    // 启动健康监测
524	    healthMonitor.start()
525	
526	    // 启动计时器
527	    this.timer = setInterval(() => {
528	      this.updateDuration()
529	    }, 1000)
530	  },
531	
532	  stopTraining() {
533	    this.isRunning = false
534	
535	    // 停止 IMU
536	    if (this.imuListener) {
537	      imuManager.removeListener(this.imuListener)
538	      this.imuListener = null
539	    }
540	    imuManager.stop()
541	
542	    // 停止健康监测
543	    healthMonitor.stop()
544	
545	    // 结束会话
546	    dataStore.endSession()
547	
548	    // 停止计时器
549	    if (this.timer) {
550	      clearInterval(this.timer)
551	      this.timer = null
552	    }
553	  },
554	
555	  handleIMUData(data) {
556	    // 数据融合
557	    const fusedData = sensorFusion.fuse(data.accel, data.gyro)
558	
559	    // 输入到挥拍检测器
560	    swingDetector.processData(fusedData)
561	  },
562	
563	  handleSwingDetected(swingData) {
564	    // 分类击球类型
565	    const classification = shotClassifier.classify(swingData, imuManager.getBuffer())
566	
567	    // 更新 UI
568	    this.totalStrokes++
569	    this.lastShotType = classification.typeName
570	
571	    // 更新击球统计
572	    const shotIndex = this.getShotIndex(classification.type)
573	    if (shotIndex >= 0) {
574	      this.shotDistribution[shotIndex].count++
575	      this.updateDistribution()
576	    }
577	
578	    // 记录到数据存储
579	    dataStore.recordSwing(classification.type)
580	
581	    // 震动反馈
582	    this.vibrate(50)
583	  },
584	
585	  handleHealthData(data) {
586	    if (data.type === 'heartRate') {
587	      this.heartRate = data.value
588	    } else if (data.type === 'calories') {
589	      this.calories = data.value
590	      dataStore.updateCalories(data.value)
591	    }
592	  },
593	
594	  getShotIndex(type) {
595	    const types = ['highClear', 'smash', 'drive', 'lift', 'drop']
596	    return types.indexOf(type)
597	  },
598	
599	  updateDistribution() {
600	    const maxCount = Math.max(...this.shotDistribution.map(s => s.count), 1)
601	    this.shotDistribution = this.shotDistribution.map(item => ({
602	      ...item,
603	      percentage: (item.count / maxCount) * 100
604	    }))
605	  },
606	
607	  updateDuration() {
608	    if (!this.startTime) return
609	    const elapsed = Math.floor((Date.now() - this.startTime) / 1000)
610	    const mins = Math.floor(elapsed / 60).toString().padStart(2, '0')
611	    const secs = (elapsed % 60).toString().padStart(2, '0')
612	    this.duration = `${mins}:${secs}`
613	  },
614	
615	  vibrate(duration) {
616	    vibrator.vibrate({
617	      mode: 'short',
618	      vibrateTime: duration || 50,
619	      fail: () => {}
620	    })
621	  },
622	
623	  pauseTraining() {
624	    this.stopTraining()
625	    router.push({
626	      uri: '/pages/pause',
627	      params: {
628	        duration: this.duration,
629	        heartRate: this.heartRate,
630	        calories: this.calories,
631	        totalStrokes: this.totalStrokes
632	      }
633	    })
634	  }
635	}
636	</script>
