234	    const day = date.getDate().toString().padStart(2, '0')
235	    const hours = date.getHours().toString().padStart(2, '0')
236	    const mins = date.getMinutes().toString().padStart(2, '0')
237	    return `${month}/${day} ${hours}:${mins}`
238	  },
